import { gsap } from 'gsap';
import { vec3, uv, mix, color } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.handlers = {};

  const timelines = [];
  const cleanupCallbacks = [];

  // ============================================================================
  // 1. BACKDROP PLANE: 7 x 5.5 units at z=-1.5 with vertical gradient
  // ============================================================================
  const backdropGeometry = new THREE.PlaneGeometry(7, 5.5);

  // Use TSL gradient shader to avoid DOM canvas access
  const topColor = color(0x0b0b10);
  const bottomColor = color(0x13131a);
  const gradientMix = mix(topColor, bottomColor, mix(0, 1, uv().y));

  const backdropMaterial = new MeshBasicNodeMaterial({
    color: gradientMix,
    toneMapped: false,
  });

  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -1.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // ============================================================================
  // 2. CAPTION KICKER: "NOVA ATELIER / CALIBRE PROGRAM" at y=1.15
  // ============================================================================
  const captionText = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    fontSize: 12,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.5,
  });
  captionText.position.set(0, 1.15, 0.1);
  captionText.renderOrder = 10;
  group.add(captionText);

  // ============================================================================
  // 3. HERO HEADLINE: "TIME, MACHINED." — Kinetic glyph-by-glyph entrance
  // ============================================================================
  const heroGroup = new THREE.Group();
  heroGroup.position.y = 0.4;
  group.add(heroGroup);

  // Create hero text with appropriate scaling for 0.62em height
  const heroText = ctx.fontAtlas.createText('TIME, MACHINED.', {
    fontSize: 48,
    color: '#e8ecf2',
    align: 'center',
  });
  heroText.renderOrder = 20;

  // Collect all glyph meshes for animation
  const allGlyphMeshes = [];
  const collectGlyphs = (node) => {
    if (node.isMesh) {
      allGlyphMeshes.push(node);
    }
    if (node.children && node.children.length > 0) {
      node.children.forEach(collectGlyphs);
    }
  };
  collectGlyphs(heroText);

  // Apply word-level z-offset for parallax: first word at z=0.12, second at z=-0.12
  const glyphCountPerWord = Math.ceil(allGlyphMeshes.length / 2);
  allGlyphMeshes.forEach((mesh, idx) => {
    const wordIndex = idx < glyphCountPerWord ? 0 : 1;
    mesh.position.z = (wordIndex === 0 ? 0.12 : -0.12);
  });

  heroGroup.add(heroText);

  // ============================================================================
  // 4. ACCENT UNDERLINE: 2.6 x 0.045-unit plane, #ff2a38 emissive
  // ============================================================================
  const underlineGeometry = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.2,
    toneMapped: false,
  });

  const underline = new THREE.Mesh(underlineGeometry, underlineMaterial);
  underline.position.set(0, -0.05, 0.15);
  underline.scale.x = 0;
  underline.renderOrder = 25;
  heroGroup.add(underline);

  // ============================================================================
  // 5. SUBHEAD: "Every calibre begins as a solid billet." at y=-0.65
  // ============================================================================
  const subheadText = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    fontSize: 14,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 350,
    letterSpacingPx: 0.2,
  });
  subheadText.position.set(0, -0.65, 0.1);
  subheadText.renderOrder = 15;
  subheadText.traverse((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(subheadText);

  // ============================================================================
  // 6. KINETIC ANIMATION: Per-glyph y entrance + stagger
  // ============================================================================

  const staggerMs = 60;
  const glyphDuration = 0.7;
  const glyphEasing = 'cubic-bezier(0.215,0.61,0.355,1)';

  const glyphAnimations = [];
  let finalGlyphTime = 0;

  allGlyphMeshes.forEach((mesh, idx) => {
    const delay = (idx * staggerMs) / 1000;
    finalGlyphTime = Math.max(finalGlyphTime, delay + glyphDuration);

    const tl = gsap.timeline({ paused: true });
    tl.fromTo(
      mesh.position,
      { y: mesh.position.y + 0.35 },
      {
        y: mesh.position.y,
        duration: glyphDuration,
        ease: glyphEasing,
      },
      0
    );

    tl.fromTo(
      mesh.material,
      { opacity: 0 },
      {
        opacity: 1,
        duration: glyphDuration,
        ease: glyphEasing,
      },
      0
    );

    glyphAnimations.push({ timeline: tl, delay });
    timelines.push(tl);
  });

  // ============================================================================
  // 7. WEIGHTED SETTLE: Triggered after final glyph lands
  // ============================================================================
  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    0
  );
  timelines.push(settleTl);

  // ============================================================================
  // 8. ACCENT UNDERLINE SCALE: Scale x 0 to 1 over 500ms
  // ============================================================================
  const underlineTl = gsap.timeline({ paused: true });
  underlineTl.fromTo(
    underline.scale,
    { x: 0 },
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  timelines.push(underlineTl);

  // ============================================================================
  // 9. SUBHEAD FADE-UP
  // ============================================================================
  const subheadTl = gsap.timeline({ paused: true });
  const subheadInitialY = subheadText.position.y;

  subheadTl.fromTo(
    subheadText.position,
    { y: subheadInitialY + 0.2 },
    {
      y: subheadInitialY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  subheadText.traverse((child) => {
    if (child.material && child.material.transparent) {
      subheadTl.fromTo(
        child.material,
        { opacity: 0 },
        {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        0
      );
    }
  });
  timelines.push(subheadTl);

  // ============================================================================
  // 10. TIMELINE SEQUENCING
  // ============================================================================

  glyphAnimations.forEach(({ timeline, delay }) => {
    timeline.play(delay);
  });

  settleTl.play(finalGlyphTime);
  underlineTl.play(finalGlyphTime + 0.12);
  subheadTl.play(finalGlyphTime + 0.05);

  // ============================================================================
  // 11. APPLY CINEMATIC PRIMITIVES
  // ============================================================================
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (primitive.name && ctx.primitives[primitive.name]) {
        const result = ctx.primitives[primitive.name](group, primitive.params || {});
        if (result && result.cleanup) {
          cleanupCallbacks.push(result.cleanup);
        }
        if (result && result.timeline) {
          timelines.push(result.timeline);
        }
      }
    });
  }

  // ============================================================================
  // 12. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });
    cleanupCallbacks.forEach((cb) => {
      if (typeof cb === 'function') {
        cb();
      }
    });

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
